from jsonb_to_recordset($wall_questions$[{"id":"u02_l05_q172","lesson_id":"u02_l05","difficulty":"medium","prompt":"ما الدلالة على عالمية الرسالة التي يبرزها توجيه الرسائل إلى حكام خارج الجزيرة العربية؟","options":[{"id":"o1","text":"أن الدعوة وُجهت إلى الناس كافة لا إلى قوم محددين"},{"id":"o4","text":"أن الزعماء كانوا من أهل مكة جميعًا"},{"id":"o3","text":"أن الرسائل اقتصرت على مسائل التجارة"},{"id":"o2","text":"أن الإسلام اقتصر على سكان المدينة"}],"correct_id":"o1","explanation":"بيّن التمهيد أن المكاتبة داخل الجزيرة وخارجها تطبيق لعموم رسالة الإسلام.","page":73},{"id":"u02_l05_q174","lesson_id":"u02_l05","difficulty":"medium","prompt":"ما الذي يفهم من عرض بقاء الحكم للملوك داخل الجزيرة العربية إذا أسلموا؟","options":[{"id":"o4","text":"أن الحكام جميعهم رفضوا الاستجابة"},{"id":"o1","text":"أن غاية الرسائل كانت الدعوة لا انتزاع المناصب"},{"id":"o2","text":"أن النبي ﷺ منعهم من إدارة شؤون بلدانهم"},{"id":"o3","text":"أن الرسائل خلت من الدعوة إلى الإيمان"}],"correct_id":"o1","explanation":"شرح الكتاب أن العرض كان سببًا في تسهيل قبول الدعوة ولم يكن الهدف الاستيلاء على المناصب.","page":74},{"id":"u02_l05_q176","lesson_id":"u02_l05","difficulty":"medium","prompt":"لماذا استقصى هرقل أخبار النبي ﷺ وسأل أبا سفيان عن نسبه وأخلاقه؟","options":[{"id":"o3","text":"ليتأكد من عدد كتبة القرآن"},{"id":"o4","text":"ليعقد اتفاقًا خاصًا بالميراث"},{"id":"o2","text":"ليتعلم التجارة في مكة فحسب"},{"id":"o1","text":"ليتحقق من حقيقة الدعوة وصاحب الرسالة قبل اتخاذ موقف"}],"correct_id":"o1","explanation":"أورد الدرس أن هرقل أراد معرفة نسب النبي ﷺ وأخلاقه وصدق دعوته.","page":76},{"id":"u02_l05_q177","lesson_id":"u02_l05","difficulty":"easy","prompt":"أي حاكم أكرم حامل الرسالة وأرسل هدية مع عدم دخوله في الإسلام؟","options":[{"id":"o4","text":"النجاشي ملك الحبشة"},{"id":"o2","text":"ملك البحرين المنذر بن ساوى"},{"id":"o1","text":"المقوقس عظيم القبط في مصر"},{"id":"o3","text":"ملكا عمان جيفر وعبد"}],"correct_id":"o1","explanation":"ذكر الكتاب أن المقوقس أكرم حامل الرسالة وأهدى للنبي ﷺ ولم يسلم.","page":76},{"id":"u02_l05_q178","lesson_id":"u02_l05","difficulty":"easy","prompt":"أي صفة كانت مهمة عند اختيار رسول يحمل كتابًا إلى حاكم في بلد آخر؟","options":[{"id":"o3","text":"الامتناع عن قراءة الرسالة"},{"id":"o4","text":"عدم معرفة الجهة التي يزورها"},{"id":"o1","text":"معرفة لغة القوم وعاداتهم والقدرة على المحاورة"},{"id":"o2","text":"الجهل بلغة المخاطبين"}],"correct_id":"o1","explanation":"أبرز الدرس اختيار السفراء وفق معرفتهم بلغات الشعوب وطبائعها.","page":76},{"id":"u02_l05_q187","lesson_id":"u02_l05","difficulty":"medium","prompt":"كيف ارتبط استشهاد حامل إحدى الرسائل قبل وصولها إلى حاكم بحدث عسكري لاحق؟","options":[{"id":"o1","text":"كان مقتل الحارث بن عمير من أسباب معركة مؤتة"},{"id":"o2","text":"كان سببًا لفتح مكة في السنة نفسها"},{"id":"o4","text":"ألغى الرسول ﷺ إرسال الرسائل جميعها"},{"id":"o3","text":"أدى مباشرة إلى غزوة بدر"}],"correct_id":"o1","explanation":"نص الإثراء على أن مقتل الحارث بن عمير الأَزدي من أسباب مؤتة.","page":77},{"id":"u02_l05_q188","lesson_id":"u02_l05","difficulty":"hard","prompt":"أي استنتاج تدعمه قصة الحارث بن عمير الأزدي من طبيعة مهمة السفير في عصر الرسالة؟","options":[{"id":"o4","text":"أن القبائل لم تتعامل مع السفراء مطلقًا"},{"id":"o3","text":"أن الرسائل كانت للتجارة ولا صلة لها بالدعوة"},{"id":"o2","text":"أن جميع سفراء النبي ﷺ لم يغادروا المدينة"},{"id":"o1","text":"أن تبليغ الرسائل قد ينطوي على خطر وتبعات سياسية"}],"correct_id":"o1","explanation":"تروي الصفحة اعتراض الحارث بن عمير ومقتله وهو في طريقه برسالة النبي ﷺ.","page":77},{"id":"u02_l06_q092","lesson_id":"u02_l06","difficulty":"medium","prompt":"لماذا أعلن النبي ﷺ وجهة الجيش قبل الخروج إلى تبوك خلافًا لعادته؟","options":[{"id":"o2","text":"لإلغاء الحاجة إلى المؤونة"},{"id":"o4","text":"لأن الغزوة لم تحتج إلى تجهيز"},{"id":"o3","text":"لقرب تبوك من المدينة جدًا"},{"id":"o1","text":"لبعد المسافة وقوة العدو وحاجة الناس إلى الاستعداد"}],"correct_id":"o1","explanation":"ذكر الكتاب طول المسافة وقوة الخصم وضرورة التهيؤ.","page":80},{"id":"u02_l06_q105","lesson_id":"u02_l06","difficulty":"medium","prompt":"لماذا أعلن النبي ﷺ وجهة تبوك مسبقًا على خلاف بعض الغزوات السابقة؟","options":[{"id":"o2","text":"لإلغاء تجهيز الجيش"},{"id":"o4","text":"لعدم الحاجة إلى مشاركة المسلمين"},{"id":"o3","text":"لقصر الطريق وسهولة السفر"},{"id":"o1","text":"لبعد المسافة وقوة الخصم والحاجة للاستعداد"}],"correct_id":"o1","explanation":"يربط الكتاب إعلان الوجهة بمتطلبات التجهيز والمسافة.","page":80},{"id":"u02_l06_q107","lesson_id":"u02_l06","difficulty":"medium","prompt":"كيف تميز موقف الصحابة الثلاثة المتخلفين عن موقف المنافقين بعد العودة؟","options":[{"id":"o4","text":"بنوا مسجد الضرار لتبرير فعلهم"},{"id":"o3","text":"أنكروا مسؤوليتهم عن التخلف"},{"id":"o1","text":"اعترفوا بتقصيرهم ولم يقدموا أعذارًا كاذبة"},{"id":"o2","text":"أخفوا الحقيقة بأعذار متفق عليها"}],"correct_id":"o1","explanation":"ذكر الكتاب صدق الصحابة الثلاثة واعترافهم بالذنب.","page":82},{"id":"u02_l06_q113","lesson_id":"u02_l06","difficulty":"medium","prompt":"ما العامل الذي جمع بين الحر الشديد وبعد المسافة وقلة المؤن في يوم تبوك؟","options":[{"id":"o2","text":"سهولة المسير دون حاجة للاستعداد"},{"id":"o4","text":"قصر المسافة بين المدينتين"},{"id":"o3","text":"انعدام الحاجة إلى التمويل"},{"id":"o1","text":"تعاظم مشقة تجهيز جيش العسرة"}],"correct_id":"o1","explanation":"أورد الكتاب هذه الظروف من أسباب تسمية الجيش بجيش العسرة.","page":80},{"id":"u02_l06_q116","lesson_id":"u02_l06","difficulty":"medium","prompt":"أي أثر سياسي نجم عن تبوك في تقدير قبائل الجزيرة لقوة الروم؟","options":[{"id":"o1","text":"تراجع هيبة الروم بعد انسحاب حلفائهم أمام المسلمين"},{"id":"o4","text":"انحصار الإسلام في المدينة وحدها"},{"id":"o3","text":"زوال كل علاقات الصلح في المنطقة"},{"id":"o2","text":"زيادة اعتقاد أن الروم لا يُواجهون"}],"correct_id":"o1","explanation":"ربط نتائج تبوك بين الانتصار دون قتال وسقوط هيبة الروم وحلفائهم.","page":83},{"id":"u02_l06_q126","lesson_id":"u02_l06","difficulty":"medium","prompt":"ما المثال الذي يثبت مشاركة النساء في تجهيز جيش تبوك بحسب النص؟","options":[{"id":"o3","text":"اشترطن إلغاء المعاهدات"},{"id":"o2","text":"منعن كل دعم للجيش"},{"id":"o1","text":"قدمن حليهن للإسهام في التجهيز"},{"id":"o4","text":"تولين توزيع أنصبة الإرث"}],"correct_id":"o1","explanation":"ذكر الدرس مشاركة النساء بالحلي في تجهيز الجيش.","page":80},{"id":"u02_l06_q132","lesson_id":"u02_l06","difficulty":"medium","prompt":"لماذا أعلن النبي ﷺ وجهته في الخروج إلى تبوك بخلاف عادته في بعض الغزوات؟","options":[{"id":"o4","text":"لأن الطريق كان قصيرًا وسهلًا"},{"id":"o1","text":"ليتمكن الناس من الاستعداد لطول الطريق وقوة العدو"},{"id":"o2","text":"لتجنب تجهيز الجيش"},{"id":"o3","text":"لإلغاء مشاركة المحتاجين"}],"correct_id":"o1","explanation":"يعلل الدرس ذلك ببعد المسافة وشدة الظروف وقوة العدو.","page":80},{"id":"u02_l06_q137","lesson_id":"u02_l06","difficulty":"hard","prompt":"ما الدلالة الإدارية لإقامة النبي ﷺ نحو عشرين يومًا في تبوك وعقده اتفاقيات مع الأمراء؟","options":[{"id":"o4","text":"استمرار القتال طوال الإقامة"},{"id":"o2","text":"الانسحاب دون أي تفاهم"},{"id":"o3","text":"إلغاء وجود القبائل في الشمال"},{"id":"o1","text":"تثبيت الأمن وبناء علاقات سلمية بعد ردع التهديد"}],"correct_id":"o1","explanation":"يربط الدرس الإقامة بعقد معاهدات الصلح مع الأمراء.","page":81},{"id":"u02_l06_q139","lesson_id":"u02_l06","difficulty":"medium","prompt":"أي مجموعة تضم الصحابة الثلاثة الذين اعترفوا بتقصيرهم في التخلف عن تبوك دون تقديم أعذار كاذبة؟","options":[{"id":"o1","text":"كعب بن مالك ومرارة بن الربيع وهلال بن أمية"},{"id":"o4","text":"كعب بن مالك ومرارة بن الربيع وعمر بن الخطاب"},{"id":"o2","text":"كعب بن مالك وعثمان بن عفان وهلال بن أمية"},{"id":"o3","text":"أبو بكر الصديق ومرارة بن الربيع وهلال بن أمية"}],"correct_id":"o1","explanation":"سمّى الدرس كعب بن مالك ومرارة بن الربيع وهلال بن أمية من المتخلفين الذين صدقوا في اعتذارهم.","page":81},{"id":"u02_l06_q142","lesson_id":"u02_l06","difficulty":"medium","prompt":"لماذا أعلن النبي ﷺ وجهة الجيش في تبوك على خلاف عادته في معارك أخرى؟","options":[{"id":"o3","text":"لأن السفر لا يحتاج تجهيزًا"},{"id":"o1","text":"لطول المسافة وقوة الخصم وحاجة الناس للاستعداد"},{"id":"o4","text":"لأن المعركة لم تتطلب نفيرًا"},{"id":"o2","text":"لأن الجيش كان قريبًا جدًا من المدينة"}],"correct_id":"o1","explanation":"بين الكتاب سبب التصريح بالوجهة من أجل الاستعداد لطول الرحلة وقوة العدو.","page":80},{"id":"u02_l06_q145","lesson_id":"u02_l06","difficulty":"medium","prompt":"ما وجه وصف أحداث تبوك بالنصر مع عدم وقوع قتال مباشر مع الروم؟","options":[{"id":"o2","text":"لأن الروم احتلوا المدينة"},{"id":"o3","text":"لأن جيش المسلمين تفرّق وهرب"},{"id":"o4","text":"لأن المسلمين ألغوا كل المعاهدات"},{"id":"o1","text":"لأن حلفاء الروم انسحبوا وتحققت هيبة المسلمين"}],"correct_id":"o1","explanation":"بيّن الدرس أن الرعب وقع في قلوب الحلفاء فانسحبوا، فعاد الجيش من غير قتال.","page":81},{"id":"u02_l06_q146","lesson_id":"u02_l06","difficulty":"hard","prompt":"ما الفائدة السياسية لإبرام النبي ﷺ معاهدات مع أمراء المناطق الشمالية بعد الوصول إلى تبوك؟","options":[{"id":"o3","text":"تحويل جميع الاتفاقيات إلى تجارة خاصة"},{"id":"o4","text":"إلغاء الصلح مع جيران المدينة"},{"id":"o2","text":"منع التواصل مع سكان تلك المناطق"},{"id":"o1","text":"تنظيم العلاقة وتأمين الحدود الشمالية للجزيرة"}],"correct_id":"o1","explanation":"أشار الكتاب إلى معاهدات الصلح مع أمراء مناطق الشمال بعد تبوك.","page":81},{"id":"u02_l06_q148","lesson_id":"u02_l06","difficulty":"medium","prompt":"ما سبب تسمية السنة التاسعة للهجرة «عام الوفود» في سياق نتائج تبوك؟","options":[{"id":"o3","text":"لاختيار خليفة جديد للمسلمين"},{"id":"o1","text":"لقدوم وفود قبائل تعلن إسلامها"},{"id":"o2","text":"لوقوع معارك في كل شهر"},{"id":"o4","text":"لهجرة سكان المدينة منها"}],"correct_id":"o1","explanation":"أورد الدرس تتابع وفود القبائل بعد تبوك وإعلانها الإسلام.","page":83},{"id":"u02_l06_q157","lesson_id":"u02_l06","difficulty":"medium","prompt":"ما الفرق بين اعتذارات المنافقين وموقف الصحابة الثلاثة الذين تخلفوا؟","options":[{"id":"o3","text":"أنكر الطرفان وقوع الخروج إلى تبوك"},{"id":"o4","text":"لم يقدم أي طرف اعتذارًا بعد العودة"},{"id":"o1","text":"اختلق المنافقون الأعذار وأقرّ الثلاثة بتقصيرهم صادقين"},{"id":"o2","text":"قدّم الصحابة الثلاثة روايات كاذبة وأقر المنافقون بالحقيقة"}],"correct_id":"o1","explanation":"روى الدرس صدق الثلاثة واعترافهم مقابل الأعذار الكاذبة للمنافقين.","page":82},{"id":"u02_l06_q161","lesson_id":"u02_l06","difficulty":"medium","prompt":"لماذا عُد يوم تبوك تحديًا كبيرًا للمسلمين رغم عدم وقوع قتال مباشر؟","options":[{"id":"o2","text":"لأنه وقع في زمن وفرة شديدة من المال والزاد"},{"id":"o1","text":"لأنه تطلب استعدادًا في ظروف صعبة ومواجهة تهديد قوي"},{"id":"o3","text":"لأن المسلمين لم يحتاجوا إلى السير خارج المدينة"},{"id":"o4","text":"لأن الروم كانوا حلفاء المسلمين جميعًا"}],"correct_id":"o1","explanation":"بيّن الدرس شدة الظروف واستعداد المسلمين لخطر الروم في تبوك.","page":79},{"id":"u02_l06_q164","lesson_id":"u02_l06","difficulty":"hard","prompt":"إذا انتشرت شائعة بهدف تثبيط أصحاب مهمة عامة؛ فأي موقف من أحداث تبوك يفسر هذا الأسلوب؟","options":[{"id":"o1","text":"محاولات المنافقين تخويف الناس من الروم وصرفهم عن الخروج"},{"id":"o4","text":"توبة الصحابة الثلاثة الصادقين"},{"id":"o3","text":"اتفاقيات الصلح مع المناطق الشمالية"},{"id":"o2","text":"مواقف المتبرعين بتجهيز الجيش"}],"correct_id":"o1","explanation":"ذكر الدرس تثبيط المنافقين للناس بالشائعات وتخويفهم من الروم.","page":81},{"id":"u02_l06_q167","lesson_id":"u02_l06","difficulty":"medium","prompt":"ما القيمة التي تجمع مشاركة عثمان بن عفان والنساء وفقراء المسلمين في تجهيز جيش العسرة؟","options":[{"id":"o3","text":"أن يترك الفقراء المشاركة إلى ما بعد انتهاء المهمة"},{"id":"o4","text":"أن تُمنع النساء من الإسهام في الأعمال العامة"},{"id":"o2","text":"أن يقتصر التجهيز على الأغنياء دون غيرهم"},{"id":"o1","text":"أن يساهم كل فرد بما يستطيع رغم تفاوت قدراته وموارده"}],"correct_id":"o1","explanation":"ذكر الدرس إنفاق عثمان بن عفان وتقديم النساء حليهن والفقراء ما استطاعوا، مما يدل على المشاركة بحسب القدرة.","page":80},{"id":"u02_l06_q172","lesson_id":"u02_l06","difficulty":"medium","prompt":"لماذا أخبر النبي ﷺ المسلمين بوجهته إلى تبوك على غير عادته في بعض الغزوات؟","options":[{"id":"o4","text":"لأن المسلمين لم يكونوا بحاجة إلى الاستعداد"},{"id":"o2","text":"حتى لا يعرفوا المقصد من الرحلة مطلقًا"},{"id":"o1","text":"ليتهيؤوا لطول المسافة وصعوبة الظروف"},{"id":"o3","text":"لأن المسافة كانت قصيرة ولا مشقة فيها"}],"correct_id":"o1","explanation":"ذكر الكتاب طول المسافة وقوة العدو سببًا لإعلان الوجهة قبل الخروج.","page":80},{"id":"u02_l06_q175","lesson_id":"u02_l06","difficulty":"easy","prompt":"من الصحابة الذين تخلفوا عن تبوك من غير عذر ثم اعترفوا بصدق؟","options":[{"id":"o3","text":"دحية الكلبي رضي الله عنه"},{"id":"o2","text":"عثمان بن عفان رضي الله عنه"},{"id":"o1","text":"كعب بن مالك رضي الله عنه"},{"id":"o4","text":"عمرو بن العاص رضي الله عنه"}],"correct_id":"o1","explanation":"عدّ الدرس كعب بن مالك أحد الصحابة الثلاثة الذين صدقوا في اعترافهم بالتخلف.","page":81},{"id":"u02_l06_q176","lesson_id":"u02_l06","difficulty":"medium","prompt":"كيف تعامل الصحابة الثلاثة مع مسؤولية التخلف عن تبوك بعد الاعتراف بخطئهم؟","options":[{"id":"o1","text":"التزموا بتوجيه النبي ﷺ بانتظار حكم الله في شأنهم"},{"id":"o3","text":"قدموا شهادات كاذبة عن الآخرين"},{"id":"o4","text":"انتقلوا فورًا إلى بلاد الشام"},{"id":"o2","text":"رفضوا الاعتراف بأي تقصير"}],"correct_id":"o1","explanation":"ذكر الكتاب أنهم أقروا بتقصيرهم والتزموا باعتزال الناس حتى نزل حكم الله بشأن توبتهم.","page":82},{"id":"u02_l06_q178","lesson_id":"u02_l06","difficulty":"easy","prompt":"أي قيمة تربوية تؤكدها مقارنة اعتذار المنافقين بموقف الصحابة الصادقين بعد تبوك؟","options":[{"id":"o1","text":"الصدق والاعتراف بالتقصير بديلان عن تقديم الأعذار الكاذبة"},{"id":"o2","text":"أن الاعتذار المختلق أصدق من تحمل المسؤولية"},{"id":"o4","text":"أن نجاح المهمة يجعل الكذب مباحًا"},{"id":"o3","text":"أن الاعتراف بالتقصير يمنع قبول التوبة"}],"correct_id":"o1","explanation":"قارن الكتاب بين أعذار المنافقين الكاذبة واعتراف الصحابة الثلاثة الصادق بتقصيرهم.","page":82},{"id":"u02_l06_q181","lesson_id":"u02_l06","difficulty":"medium","prompt":"ما الذي يفسر مبادرة النبي ﷺ إلى الخروج لتبوك قبل وصول قوات الروم إلى المدينة؟","options":[{"id":"o4","text":"حصر التحرك في شأن تجاري عابر"},{"id":"o1","text":"مواجهة التهديد ومنع امتداد العدوان إلى المجتمع المسلم"},{"id":"o3","text":"طلب قتال قبائل لا وجود لها في الخبر"},{"id":"o2","text":"ترك المدينة بلا تخطيط لأي مواجهة"}],"correct_id":"o1","explanation":"ذكر الدرس أخبار حشود الروم وحلفائهم وعزم النبي ﷺ على مواجهتهم قبل وصولهم.","page":80},{"id":"u02_l06_q182","lesson_id":"u02_l06","difficulty":"hard","prompt":"في أي جانب يعد يوم تبوك شاهدًا على اتخاذ القرار بناء على معطيات تهديد خارجي؟","options":[{"id":"o3","text":"تجاهل أخبار الحدود حتى وقوع الهجوم"},{"id":"o2","text":"إلغاء المشورة في كل أمر مستقبلًا"},{"id":"o4","text":"رفض أي عمل دفاعي ولو ثبت الخطر"},{"id":"o1","text":"الاستعداد المبكر بعد ورود خبر تحشد القوى المعادية"}],"correct_id":"o1","explanation":"يربط الدرس سبب الخروج بخبر استعداد الروم للهجوم على المدينة.","page":80},{"id":"u02_l06_q184","lesson_id":"u02_l06","difficulty":"hard","prompt":"لماذا عُرف جيش تبوك بجيش العسرة؟","options":[{"id":"o2","text":"لأنه خرج في وقت وفرة غير محدودة"},{"id":"o4","text":"لأن المسلمين لم يحتاجوا إلى تجهيز أصلًا"},{"id":"o1","text":"لشدة الظروف وقلة الموارد أثناء التجهيز والخروج"},{"id":"o3","text":"لأن المعركة دارت في أرض خالية من الناس"}],"correct_id":"o1","explanation":"أشار الدرس إلى شدة الظروف التي صاحبت تجهيز الجيش وخروجه.","page":81},{"id":"u02_l06_q187","lesson_id":"u02_l06","difficulty":"medium","prompt":"كيف انعكس وصول المسلمين إلى تبوك وانصراف عدوهم عن القتال على صورة الدولة الإسلامية؟","options":[{"id":"o4","text":"جعل الشائعات حقيقة ثابتة"},{"id":"o1","text":"أظهر قدرتها على رد العدوان دون وقوع مواجهة مباشرة"},{"id":"o2","text":"أثبت غياب القوة المنظمة عن المسلمين"},{"id":"o3","text":"أوقف اتصال القبائل بالإسلام"}],"correct_id":"o1","explanation":"ذكر الدرس تحقق نصر معنوي وانكسار هيبة الروم دون قتال.","page":83},{"id":"u02_l06_q188","lesson_id":"u02_l06","difficulty":"hard","prompt":"ما الصلة بين نتائج يوم تبوك وازدياد وفود القبائل إلى المدينة في السنة التاسعة؟","options":[{"id":"o3","text":"جعلت عام الوفود سابقًا ليوم بدر"},{"id":"o4","text":"لم يكن لظهور قوة المسلمين أثر في الجزيرة"},{"id":"o2","text":"منعت النتائج كل قبيلة من مراسلة المدينة"},{"id":"o1","text":"عززت هيبة الدولة فتسارعت قبائل إلى إعلان إسلامها"}],"correct_id":"o1","explanation":"ربط الكتاب نتائج تبوك بمجيء الوفود وإعلان قبائل إسلامها في عام الوفود.","page":83},{"id":"u02_l07_q092","lesson_id":"u02_l07","difficulty":"medium","prompt":"مناقشة صحابية لعمر بن الخطاب رضي الله عنه في قرار عام مثال على أي حق؟","options":[{"id":"o1","text":"تقديم النصيحة لولي الأمر"},{"id":"o4","text":"التخلي عن الحقوق السياسية"},{"id":"o2","text":"إلغاء الشورى"},{"id":"o3","text":"منع المشاركة في الرأي"}],"correct_id":"o1","explanation":"أورد الكتاب هذه القصة مثالًا لإبداء النصح.","page":86},{"id":"u02_l07_q105","lesson_id":"u02_l07","difficulty":"medium","prompt":"ما الدلالة من قبول عمر بن الخطاب نصيحة صحابية بشأن المهور؟","options":[{"id":"o1","text":"مشروعية إبداء المرأة النصح في الشأن العام"},{"id":"o4","text":"أن أحكام الأسرة تنفصل عن النصوص"},{"id":"o2","text":"قصر النصيحة على الرجال"},{"id":"o3","text":"عدم جواز الاعتراض المهذب على قرار"}],"correct_id":"o1","explanation":"استدل الكتاب بالموقف على حق المرأة في النصيحة.","page":86},{"id":"u02_l07_q113","lesson_id":"u02_l07","difficulty":"medium","prompt":"أي مجال من الحقوق السياسية تجسده بيعة النساء للنبي ﷺ بعد الهجرة؟","options":[{"id":"o4","text":"تنظيم شؤون التجارة الخاصة"},{"id":"o2","text":"تملك المال وحده"},{"id":"o3","text":"الإنفاق على الأسرة فقط"},{"id":"o1","text":"المشاركة في صنع القرار وبناء الدولة"}],"correct_id":"o1","explanation":"عرض الدرس البيعة ضمن مشاركة النساء في صنع القرار.","page":86},{"id":"u02_l07_q127","lesson_id":"u02_l07","difficulty":"medium","prompt":"بأي نصيحة أسهمت السيدة خديجة رضي الله عنها بعد نزول الوحي أول مرة؟","options":[{"id":"o4","text":"منعت السؤال عن معنى الوحي"},{"id":"o3","text":"أوصت بترك مكة فورًا دون تشاور"},{"id":"o1","text":"أشارت بالذهاب إلى ورقة بن نوفل"},{"id":"o2","text":"أمرت بإيقاف تبليغ الرسالة"}],"correct_id":"o1","explanation":"ذكر الدرس مشورة خديجة بالرجوع إلى ورقة بن نوفل.","page":87},{"id":"u02_l07_q132","lesson_id":"u02_l07","difficulty":"medium","prompt":"ما الدلالة السياسية لقبول عمر بن الخطاب رضي الله عنه نصيحة صحابية في أمر المهور؟","options":[{"id":"o1","text":"مشروعية مناقشة المرأة للقرارات العامة بالحجة"},{"id":"o4","text":"منع الاحتجاج بالنص الشرعي"},{"id":"o3","text":"رفض مراجعة القرار بعد إعلانه"},{"id":"o2","text":"حصر النصح في أصحاب المناصب"}],"correct_id":"o1","explanation":"ساق الكتاب القصة لبيان حق المرأة في تقديم النصيحة لولي الأمر.","page":86},{"id":"u02_l07_q133","lesson_id":"u02_l07","difficulty":"medium","prompt":"أي صورة من المشاركة السياسية جسدتها مبايعة نساء الأنصار في العقبة الثانية؟","options":[{"id":"o2","text":"إدارة متجر خاص"},{"id":"o1","text":"المشاركة في صنع القرار العام"},{"id":"o4","text":"تقسيم الميراث"},{"id":"o3","text":"تعلم القراءة وحده"}],"correct_id":"o1","explanation":"ذكر الدرس بيعة النساء مثالًا للمشاركة في بناء الدولة.","page":86},{"id":"u02_l07_q135","lesson_id":"u02_l07","difficulty":"medium","prompt":"ما النتيجة الشرعية التي أكدتها موافقة النبي ﷺ على أمان أم هانئ رضي الله عنها؟","options":[{"id":"o1","text":"صحة منح المرأة المسلمة الأمان"},{"id":"o4","text":"قصر الأمان على الرجال"},{"id":"o2","text":"عدم نفاذ الأمان إلا من الحاكم"},{"id":"o3","text":"وجوب إلغاء كل إجارة"}],"correct_id":"o1","explanation":"نص الكتاب على إجازته ﷺ أمان أم هانئ وعلى تقرير الفقهاء لهذا الحق.","page":87},{"id":"u02_l07_q140","lesson_id":"u02_l07","difficulty":"hard","prompt":"طالبت مواطنة بمناقشة قرار يمس المصلحة العامة وقدمت دليلًا؛ في أي جانب من الحقوق السياسية يندرج فعلها؟","options":[{"id":"o2","text":"المهر والميراث"},{"id":"o1","text":"إبداء النصيحة والمشاركة في الشأن العام"},{"id":"o3","text":"الحضانة والرعاية الأسرية فقط"},{"id":"o4","text":"الانتفاع بأرض زراعية"}],"correct_id":"o1","explanation":"يصف الدرس تقديم النصح لولي الأمر بوصفه مشاركة سياسية للمرأة.","page":86},{"id":"u02_l07_q142","lesson_id":"u02_l07","difficulty":"medium","prompt":"ما المغزى من مناقشة امرأة لعمر بن الخطاب رضي الله عنه في تحديد المهور وتراجعه عن رأيه؟","options":[{"id":"o4","text":"إلغاء الاحتكام للنصوص"},{"id":"o1","text":"إقرار حق المرأة في النصيحة والنقاش في شأن عام"},{"id":"o3","text":"قصر النصيحة على كبار الرجال"},{"id":"o2","text":"منع مشاركة النساء في الرأي العام"}],"correct_id":"o1","explanation":"يذكر الدرس موقفه مثالًا على إبداء المرأة النصح ومراجعته له.","page":86},{"id":"u02_l07_q152","lesson_id":"u02_l07","difficulty":"medium","prompt":"ما الذي يدل عليه قبول عمر بن الخطاب رضي الله عنه نصيحة امرأة في مسألة المهور؟","options":[{"id":"o4","text":"إمكان إلغاء الاستدلال بالقرآن بسبب الرأي"},{"id":"o3","text":"أن النصيحة لا تكون إلا من الحاكم"},{"id":"o2","text":"حرمان المرأة من إبداء النصيحة"},{"id":"o1","text":"جواز مشاركة المرأة بالرأي في الشؤون العامة وقبول الحجة"}],"correct_id":"o1","explanation":"ساق الكتاب الموقف شاهدًا على حق المرأة في تقديم النصيحة ولي الأمر.","page":86},{"id":"u02_l07_q154","lesson_id":"u02_l07","difficulty":"medium","prompt":"ما الذي تشترك فيه إجارة زينب وأم هانئ في تحليل الحقوق السياسية؟","options":[{"id":"o1","text":"إقرار حق المسلمة في منح الأمان واحترام عهدها"},{"id":"o3","text":"حصر العهود في التجارة فقط"},{"id":"o2","text":"الامتناع عن اتخاذ أي قرار مجتمعي"},{"id":"o4","text":"إلغاء حق المجتمع في الوفاء بالأمان"}],"correct_id":"o1","explanation":"أبرز الدرس إقرار النبي ﷺ إجارة زينب وأم هانئ بوصفه مظهرًا لحق الأمان.","page":87},{"id":"u02_l07_q162","lesson_id":"u02_l07","difficulty":"medium","prompt":"ما نوع الحق الذي جسّده قبول عمر بن الخطاب رأي صحابية ناقشته في المهور؟","options":[{"id":"o2","text":"التنازل عن الحق في التعليم"},{"id":"o4","text":"الإعفاء من كل مسؤولية اجتماعية"},{"id":"o3","text":"الإشراف على أحكام المواريث فقط"},{"id":"o1","text":"إبداء النصح لولي الأمر ومناقشة شأن عام"}],"correct_id":"o1","explanation":"ذكر الكتاب قبول عمر نصيحة امرأة في شأن المهور نموذجًا للنصح السياسي.","page":86},{"id":"u02_l07_q167","lesson_id":"u02_l07","difficulty":"medium","prompt":"أي مجال لخدمة المسلمين تجلّى في دور أم عطية رضي الله عنها أثناء الغزوات؟","options":[{"id":"o3","text":"تغيير أنصبة المواريث"},{"id":"o1","text":"إعداد الطعام ورعاية المصابين والمرضى"},{"id":"o4","text":"كتابة رسائل الحكام فقط"},{"id":"o2","text":"جمع الضرائب من سكان المدن"}],"correct_id":"o1","explanation":"ورد عن أم عطية قيامها بالخدمة وإعداد الطعام ورعاية المرضى والمصابين.","page":88},{"id":"u02_l07_q172","lesson_id":"u02_l07","difficulty":"medium","prompt":"ما المبدأ الذي يفسر قبول الخليفة عمر رضي الله عنه نصيحة امرأة بشأن المهور؟","options":[{"id":"o2","text":"منع المرأة من الحديث في القضايا العامة"},{"id":"o3","text":"إلزام ولي الأمر بعدم الإصغاء لأي نقد"},{"id":"o4","text":"حصر النصيحة في العلاقات التجارية"},{"id":"o1","text":"إمكان تقديم المرأة النصح في الشأن العام ومراجعته بالدليل"}],"correct_id":"o1","explanation":"أورد الدرس قبول عمر نصيحة صحابية وتراجعه عن قراره في المهور.","page":86},{"id":"u02_l07_q174","lesson_id":"u02_l07","difficulty":"medium","prompt":"كيف يوضح موقف السيدة رقية رضي الله عنها مفهوم المشاركة في بناء المجتمع والدعوة؟","options":[{"id":"o1","text":"شاركت في الهجرة إلى الحبشة وتحملت الأذى نصرة لدينها"},{"id":"o2","text":"امتنعت عن الهجرة رغم حاجتها إليها"},{"id":"o3","text":"منعت النساء من الانتقال إلى المدينة"},{"id":"o4","text":"اختصت بمهمة تنظيم الانتخابات المعاصرة"}],"correct_id":"o1","explanation":"ذكر الكتاب هجرة رقية بنت رسول الله ﷺ وزوجها عثمان إلى الحبشة.","page":87},{"id":"u02_l07_q175","lesson_id":"u02_l07","difficulty":"easy","prompt":"أي حق جسّده إقرار النبي ﷺ أمان أم هانئ رضي الله عنها لبعض من استجاروا بها؟","options":[{"id":"o1","text":"حق المرأة في إعطاء الأمان"},{"id":"o2","text":"حق التصرف في أموال اليتيم دون قيد"},{"id":"o4","text":"حق تجريد الناس من الجنسية"},{"id":"o3","text":"حق إلغاء أحكام القضاء"}],"correct_id":"o1","explanation":"أقر النبي ﷺ إجارة أم هانئ كما أورد الدرس في باب الحقوق السياسية.","page":87},{"id":"u02_l07_q176","lesson_id":"u02_l07","difficulty":"medium","prompt":"أي موقف تاريخي يوضح مساهمة النساء في خدمة المجتمع خلال الأحداث الصعبة دون حصر أدوارهن في اتخاذ القرار؟","options":[{"id":"o3","text":"حظر النساء من تعلم الإسعاف"},{"id":"o1","text":"تقديم الطعام والرعاية للمصابين كما في رواية أم عطية"},{"id":"o2","text":"امتناع النساء عن إسعاف من يحتاج إلى المساعدة"},{"id":"o4","text":"قصر كل مشاركة عامة على التصويت"}],"correct_id":"o1","explanation":"ذكر الدرس قيام نساء بإعداد الطعام وإغاثة المصابين ورعاية المرضى.","page":88},{"id":"u02_l07_q178","lesson_id":"u02_l07","difficulty":"easy","prompt":"أي عبارة تميز الترشح للانتخابات عن التصويت فيها وفق شرح الحقوق السياسية؟","options":[{"id":"o4","text":"الترشح يقتصر على العمل التطوعي دون المجالس"},{"id":"o2","text":"الترشح إبداء رأي في الطعام والشراب"},{"id":"o1","text":"الترشح طلب تمثيل الناس في المجالس بينما الانتخاب اختيار المرشح"},{"id":"o3","text":"الانتخاب تعيين الأشخاص بغير مشاركة الناخبين"}],"correct_id":"o1","explanation":"ميّز الدرس بين حق الانتخاب لاختيار الممثلين وحق الترشح لعرض الشخص نفسه على الناخبين.","page":88},{"id":"u02_l07_q181","lesson_id":"u02_l07","difficulty":"medium","prompt":"كيف يدخل تقديم المرأة نصيحة لولي الأمر في مفهوم الحقوق السياسية؟","options":[{"id":"o2","text":"إنه شأن منزلي لا علاقة له بالدولة"},{"id":"o1","text":"إنه مشاركة في توجيه القرار ورعاية الشأن العام"},{"id":"o4","text":"إنه وظيفة عسكرية مفروضة على الجميع"},{"id":"o3","text":"إنه إلغاء لمسؤولية بقية أفراد المجتمع"}],"correct_id":"o1","explanation":"عرض الدرس نصح ولي الأمر من وجوه مشاركة المرأة في الشؤون السياسية.","page":86},{"id":"u02_l07_q183","lesson_id":"u02_l07","difficulty":"medium","prompt":"ما دلالة مشاركة السيدة رقية بنت رسول الله ﷺ في الهجرة إلى الحبشة؟","options":[{"id":"o2","text":"أن الهجرة لم تشمل إلا الرجال"},{"id":"o4","text":"أن المشاركة السياسية بدأت بعد الفتوحات فقط"},{"id":"o3","text":"أن النساء لم يعرفن الابتلاء في سبيل العقيدة"},{"id":"o1","text":"تحمّل النساء المشقة في سبيل الدعوة منذ بدايات الإسلام"}],"correct_id":"o1","explanation":"ساق الكتاب رقية بنت النبي ﷺ مع زوجها عثمان في أوائل المهاجرين إلى الحبشة.","page":87},{"id":"u03_l01_q091","lesson_id":"u03_l01","difficulty":"medium","prompt":"حين يتعرض طالب لكلام جارح فيرد بكلام طيب دون انتقام، فأي خُلُق من أخلاق عباد الرحمن يطبّق؟","options":[{"id":"o2","text":"التفاخر بالنسب"},{"id":"o3","text":"الإسراف في الإنفاق"},{"id":"o1","text":"الحلم والإعراض عن الجاهلين"},{"id":"o4","text":"الابتعاد عن أداء النوافل"}],"correct_id":"o1","explanation":"بيّن الدرس أن عباد الرحمن لا يقابلون الإساءة بمثلها بل بالقول الطيب.","page":94},{"id":"u03_l01_q096","lesson_id":"u03_l01","difficulty":"medium","prompt":"يدعو شخص أن يكون أهله وأبناؤه قدوة في الخير؛ أي معنى من معاني آيات الفرقان جسّد؟","options":[{"id":"o4","text":"الرضا بإهمال شؤون الأبناء"},{"id":"o3","text":"الانصراف عن صلاح الأسرة"},{"id":"o2","text":"حصر الخير في النفس وحدها"},{"id":"o1","text":"تحمّل المسؤولية تجاه الأقربين وطلب الهداية لهم"}],"correct_id":"o1","explanation":"يشرح الدرس دعاء عباد الرحمن باعتباره محبة الخير للأهل وتحمل مسؤوليتهم.","page":97},{"id":"u03_l01_q106","lesson_id":"u03_l01","difficulty":"medium","prompt":"ما الفارق بين الإنفاق المعتدل والإقتار في صفات عباد الرحمن؟","options":[{"id":"o1","text":"المعتدل يعطي الحقوق دون إسراف والإقتار يمنع وصول المال لمستحقيه"},{"id":"o4","text":"كلاهما يعني تجاوز الحاجة في الإنفاق"},{"id":"o2","text":"الاعتدال هو منع كل نفقة"},{"id":"o3","text":"الإقتار هو إنفاق المال في جميع المصالح"}],"correct_id":"o1","explanation":"شرح الكتاب الوسط في الإنفاق وأثر البخل على المستحقين.","page":95},{"id":"u03_l01_q108","lesson_id":"u03_l01","difficulty":"medium","prompt":"ما موقف عباد الرحمن من مجالس اللغو عند المرور بها اتفاقًا؟","options":[{"id":"o3","text":"ينقلون كلامها للإيذاء"},{"id":"o2","text":"يقصدونها لتوسيع الجدل"},{"id":"o1","text":"لا يشاركون فيها ويحافظون على كرامتهم"},{"id":"o4","text":"يلزمون الجميع بحضورها"}],"correct_id":"o1","explanation":"شرح الكتاب مرورهم دون مشاركة في اللغو.","page":96},{"id":"u03_l01_q110","lesson_id":"u03_l01","difficulty":"hard","prompt":"تعرض شخص لإساءة فاختار قولًا طيبًا ولم يقابلها بمثلها؛ أي قيمة جمعها من صفات عباد الرحمن؟","options":[{"id":"o2","text":"التكبر على الناس"},{"id":"o3","text":"الانسحاب من كل مسؤولية"},{"id":"o1","text":"الحلم والإعراض عن الجاهلين دون انتصار للنفس"},{"id":"o4","text":"إساءة الظن بكل مخالف"}],"correct_id":"o1","explanation":"يشرح الكتاب الإعراض عن الجاهلين بالحلم والكلمة الطيبة.","page":94},{"id":"u03_l01_q113","lesson_id":"u03_l01","difficulty":"medium","prompt":"ما دلالة إضافة «عباد» إلى «الرحمن» في مطلع وصف عباد الرحمن؟","options":[{"id":"o2","text":"التقليل من قدر العبادة"},{"id":"o1","text":"تشريف العباد المؤمنين وتكريمهم"},{"id":"o4","text":"إلغاء الفرق بين الطاعة والمعصية"},{"id":"o3","text":"حصر الرحمة في الدنيا"}],"correct_id":"o1","explanation":"ذكر الشرح أن إضافة العبودية إلى اسم الرحمن تشريف وتكريم.","page":94},{"id":"u03_l01_q115","lesson_id":"u03_l01","difficulty":"medium","prompt":"ما النتيجة الاجتماعية للإقتار المذموم وفق تفسير الآيات؟","options":[{"id":"o2","text":"استفادة جميع المحتاجين من المال"},{"id":"o4","text":"عدم تأثر الأسرة بالإنفاق"},{"id":"o3","text":"انتشار الصدقة بلا حدود"},{"id":"o1","text":"حرمان المستحقين من نفع المال وحبس المنفعة"}],"correct_id":"o1","explanation":"ذكر الكتاب أن الإقتار يمنع نفع المال عن مالكه ومن يستحقه.","page":95},{"id":"u03_l01_q117","lesson_id":"u03_l01","difficulty":"medium","prompt":"بم يستقبل الملائكة عباد الرحمن في جزائهم كما شرحت الآيات؟","options":[{"id":"o3","text":"تجاهل أعمالهم الصالحة"},{"id":"o2","text":"اللوم على طلب الهداية"},{"id":"o4","text":"حرمانهم من كل نعيم"},{"id":"o1","text":"التكريم والاحترام والترحيب"}],"correct_id":"o1","explanation":"عدد الدرس استقبال الملائكة بالتكريم والترحيب من جزاء عباد الرحمن.","page":97},{"id":"u03_l01_q118","lesson_id":"u03_l01","difficulty":"hard","prompt":"ما مغزى التعبير باسم الإشارة الدال على البعد في الحديث عن جزاء عباد الرحمن وفق الملاحظة اللغوية؟","options":[{"id":"o4","text":"الإشارة إلى قرب المكان الدنيوي"},{"id":"o1","text":"إبراز رفعة منزلتهم وعلو مكانتهم"},{"id":"o2","text":"الدلالة على قلة عددهم تحديدًا"},{"id":"o3","text":"إلغاء وصف الصبر في الجزاء"}],"correct_id":"o1","explanation":"ربطت الملاحظة اللغوية اسم الإشارة بالمكانة العالية لعباد الرحمن.","page":98},{"id":"u03_l01_q119","lesson_id":"u03_l01","difficulty":"hard","prompt":"ما العلاقة بين الاستغفار والعمل الصالح في مفهوم التوبة الذي قررته الآيات؟","options":[{"id":"o1","text":"العمل الصالح قرينة عملية على صدق التوبة"},{"id":"o3","text":"تكرار الخطأ بلا تراجع شرط للتوبة"},{"id":"o2","text":"مجرد النطق بالتوبة يغني عن كل تغيير"},{"id":"o4","text":"التوبة تلغي الحاجة إلى اجتناب المنكر"}],"correct_id":"o1","explanation":"جعل الكتاب اقتران التوبة بالعمل الصالح من علامات صدقها.","page":96},{"id":"u03_l01_q123","lesson_id":"u03_l01","difficulty":"hard","prompt":"لماذا لا يقتصر معنى المشي هونًا في وصف عباد الرحمن على طريقة حركة القدمين؟","options":[{"id":"o2","text":"لأنه يتعلق بسرعة السير فقط"},{"id":"o3","text":"لأنه يعني العزلة عن المجتمع"},{"id":"o1","text":"لأنه يشمل السيرة والسلوك العملي والتواضع مع الناس"},{"id":"o4","text":"لأنه يصف هيئة اللباس وحدها"}],"correct_id":"o1","explanation":"وسّع الدرس معنى المشي هونًا ليشمل طريقة العيش والتعامل.","page":94},{"id":"u03_l01_q124","lesson_id":"u03_l01","difficulty":"medium","prompt":"ما الأسلوب الذي يتبعه عباد الرحمن عند الإساءة إليهم من الجاهلين؟","options":[{"id":"o3","text":"الانشغال بملاحقة كل مسيء"},{"id":"o1","text":"مقابلة الإساءة بقول طيب وتجنب ردها بمثلها"},{"id":"o4","text":"الانتقام بلا ضابط"},{"id":"o2","text":"الإساءة إلى المسيء أشد"}],"correct_id":"o1","explanation":"بيّن النص الحلم والإعراض عن الجاهلين مع القول الطيب.","page":94},{"id":"u03_l01_q130","lesson_id":"u03_l01","difficulty":"medium","prompt":"إلى ماذا يشير دعاء عباد الرحمن بصلاح أهلهم وأن يكونوا قدوة للمتقين؟","options":[{"id":"o2","text":"اقتصار الصلاح على الفرد دون الأسرة"},{"id":"o3","text":"تقديم الشهرة على السلوك"},{"id":"o4","text":"رفض العمل لصالح المجتمع"},{"id":"o1","text":"حرصهم على صلاح أنفسهم ومن حولهم"}],"correct_id":"o1","explanation":"وصل الدرس بين دعاء الأسرة وصلاح المجتمع والقدوة الحسنة.","page":97},{"id":"u03_l01_q132","lesson_id":"u03_l01","difficulty":"medium","prompt":"لماذا كانت إضافة كلمة «عباد» إلى «الرحمن» تشريفًا لأصحاب الصفات المذكورة؟","options":[{"id":"o3","text":"لأنها تتعلق بالنسب القبلي"},{"id":"o4","text":"لأنها تحصر الخير في فئة معينة"},{"id":"o2","text":"لأنها تعفيهم من التكاليف"},{"id":"o1","text":"لأنها تنسبهم إلى رحمة الله وتكرمهم"}],"correct_id":"o1","explanation":"بين الدرس أن الإضافة تشريف وتكريم لعباد الرحمن.","page":94},{"id":"u03_l01_q136","lesson_id":"u03_l01","difficulty":"medium","prompt":"ماذا يضيف العمل الصالح إلى التوبة الواردة في آيات الفرقان؟","options":[{"id":"o1","text":"يبرهن على صدق التوبة وجديتها"},{"id":"o3","text":"يجعل الخطأ مباحًا"},{"id":"o2","text":"يلغي الحاجة إلى ترك المعصية"},{"id":"o4","text":"يحصر التوبة بالأقوال"}],"correct_id":"o1","explanation":"ذكر الكتاب اقتران التوبة الصادقة بالعمل الصالح.","page":96}]$wall_questions$::jsonb)
